package com.quincaisoft.platformcontrol.application;import com.quincaisoft.platformcontrol.api.PlatformService;import com.quincaisoft.platformcontrol.infrastructure.OnboardingRequest;import jakarta.persistence.*;import org.springframework.stereotype.Service;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.security.access.AccessDeniedException;import java.util.*;import java.util.function.*;import java.time.*;
@Service public class DefaultPlatformService implements PlatformService{private final EntityManager em;private final TransactionTemplate tx;public DefaultPlatformService(EntityManager em,PlatformTransactionManager manager){this.em=em;tx=new TransactionTemplate(manager);}private UUID actor(){var auth=SecurityContextHolder.getContext().getAuthentication();if(!(auth instanceof JwtAuthenticationToken jwt))throw new AccessDeniedException("Platform identity required");return UUID.fromString(jwt.getToken().getSubject());}private <T>T scoped(Supplier<T> action){UUID actor=actor();return tx.execute(status->{em.createNativeQuery("select set_config('app.platform_actor',:a,true)").setParameter("a",actor.toString()).getSingleResult();Number found=(Number)em.createNativeQuery("select count(*) from platform_operator where actor_id=:a and active").setParameter("a",actor).getSingleResult();if(found.longValue()!=1)throw new AccessDeniedException("Enrolled active platform operator required");return action.get();});}private Item view(OnboardingRequest r){return new Item(r.id,r.displayName,r.requestedBy,r.approvedBy,r.status,r.reason,Long.toString(r.version),r.createdAt);}public List<Item> list(){return scoped(()->em.createQuery("select r from OnboardingRequest r order by r.createdAt desc,r.id",OnboardingRequest.class).setMaxResults(100).getResultList().stream().map(this::view).toList());}
public Item get(UUID id){var auth=SecurityContextHolder.getContext().getAuthentication();if(auth==null||auth.getAuthorities().stream().noneMatch(a->a.getAuthority().equals("SCOPE_platform:tenants:read")))throw new AccessDeniedException("Platform read capability required");return scoped(()->{var r=em.find(OnboardingRequest.class,Objects.requireNonNull(id));if(r==null)throw new NoSuchElementException("Request not found");return view(r);});}
public Item request(Request input){if(input==null||input.operationId()==null||input.displayName()==null||input.displayName().isBlank()||input.displayName().length()>120||input.reason()==null||input.reason().isBlank()||input.reason().length()>2000)throw new IllegalArgumentException("Operation, name and reason required");return scoped(()->{var actor=actor();em.createNativeQuery("select 1 from pg_advisory_xact_lock(hashtextextended(:k,0))").setParameter("k","platform:"+input.operationId()).getSingleResult();var existing=em.find(OnboardingRequest.class,input.operationId());if(existing!=null){if(!existing.requestedBy.equals(actor)||!existing.displayName.equals(input.displayName())||!existing.reason.equals(input.reason()))throw new IllegalStateException("Operation reused");return new Item(existing.id,existing.displayName,existing.requestedBy,null,"REQUESTED",existing.reason,"0",existing.createdAt);}var r=new OnboardingRequest();r.id=input.operationId();r.displayName=input.displayName();r.reason=input.reason();r.requestedBy=actor;r.status="REQUESTED";r.createdAt=Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MICROS);em.persist(r);em.flush();return view(r);});}
public Item approve(UUID id,Review input){if(input==null||input.operationId()==null)throw new IllegalArgumentException("Operation required");return scoped(()->{var r=em.find(OnboardingRequest.class,id,LockModeType.PESSIMISTIC_WRITE);if(r==null)throw new NoSuchElementException("Request not found");if(input.operationId().equals(r.approvalOperation)){if(!actor().equals(r.approvedBy))throw new AccessDeniedException("Review belongs to another operator");return view(r);}if(r.version!=input.version()||!r.status.equals("REQUESTED"))throw new IllegalStateException("Review version changed");if(r.requestedBy.equals(actor()))throw new AccessDeniedException("Separate platform reviewer required");r.approvedBy=actor();r.approvalOperation=input.operationId();r.status="APPROVED_FOR_PROVISIONING";em.flush();return view(r);});}}
